TransactionValueTrend = {
	init: async function (app, container) { 
		var query = "B2B/ActiveTransaction/StatsByCalendarMonth()?systemId=" + app.Config.B2B.TransactionSource;
		await api.get(query).then(function(data) {
			data.value = data.value.sort(function(a,b) { return new Date(b.CalendarMonth + "-01") - new Date(a.CalendarMonth + "-01"); });
			data.value.length = 12;
			data.value.reverse();
			TransactionValueTrend.initTransactionCountsChart(container, data.value);
		});
	},

	initChart: function(args, element) {
		var chart = new Chart(element, args);
		chart.init();
		return chart;
	},

	initTransactionCountsChart: function(container, data) {
		console.log({ component: "TransactionValueTrend", data: data });
			var args = {
				showLegend: true,
				valueTemplate: "#: kendo.toString(value, type.aggregateMoneyFormat)#",
				tooltipTemplate: "#= series.name #: #= kendo.toString(value, type.aggregateMoneyFormat) #",
				series: [
					{ name: "Average", data: data.map(i => i.Average) },
					{ name: "Low", data: data.map(i => i.Min) }, 
					{ name: "High", data: data.map(i => i.Max) }
				],
				categories: data.map(i => i.CalendarMonth),
				max: data.map(i => i.Count).sort(function(a,b){return b - a})[0],
				type: "column"
			};
			args.max = data.map(i => i.Max).sort(function(a,b) {  return b - a; })[0];

			return TransactionValueTrend.initChart(args, $("[name=transactionCount]", container));
	}
};
